234:     for vector in 0..EXCEPTION_COUNT {
235:         // SAFETY: The assembly table contains exactly 32 stub addresses.
236:         let handler = unsafe { stubs.add(vector).read() } as u64;
237:         let ist = if vector == 8 { 1 } else { 0 };
238:         // SAFETY: `vector` is bounded by the statically allocated 256-entry IDT.
239:         unsafe {
240:             idt_entries
241:                 .add(vector)
242:                 .write(IdtEntry::interrupt_gate(handler, ist));
243:         }
244:     }
245: 
246:     let irq_stubs = core::ptr::addr_of!(irq_stub_table).cast::<usize>();
247:     for vector in IRQ_FIRST_VECTOR..=IRQ_LAST_VECTOR {
248:         // SAFETY: The assembly table contains one stub for each allocated vector.
249:         let handler = unsafe { irq_stubs.add(vector - IRQ_FIRST_VECTOR).read() } as u64;
250:         // SAFETY: `vector` is bounded by the statically allocated 256-entry IDT.
251:         unsafe {
252:             idt_entries
253:                 .add(vector)
254:                 .write(IdtEntry::interrupt_gate(handler, 0));
255:         }
256:     }
257:     // SAFETY: The final table entry is the dedicated 0xff spurious-IRQ stub.
258:     let spurious_handler = unsafe { irq_stubs.add(IRQ_VECTOR_COUNT).read() } as u64;
259:     // SAFETY: The APIC spurious vector is a valid IDT index.
260:     unsafe {
261:         idt_entries
262:             .add(APIC_SPURIOUS_VECTOR)
263:             .write(IdtEntry::interrupt_gate(spurious_handler, 0));
264:     }
265: 
266:     let idtr = DescriptorTablePointer {
267:         limit: (size_of::<IdtTable>() - 1) as u16,
268:         base: core::ptr::addr_of!(IDT) as u64,
269:     };
270:     // SAFETY: Every architectural exception gate is initialized in static storage.
271:     unsafe { asm!("lidt [{}]", in(reg) &idtr, options(readonly, nostack, preserves_flags)) };
272: }
