378: fn irq_spin_lock_preserves_interrupt_state() -> bool {
379:     use rustix_kernel::sync::IrqSpinLock;
380: 
381:     fn interrupts_enabled() -> bool {
382:         let flags: u64;
383:         // SAFETY: Reading RFLAGS is non-mutating in the CPL 0 QEMU probe.
384:         unsafe { asm!("pushfq", "pop {}", out(reg) flags) };
385:         flags & (1 << 9) != 0
386:     }
387: 
388:     let lock = IrqSpinLock::new(());
389:     let initially_enabled = interrupts_enabled();
390:     let masked_while_held = {
391:         let _guard = lock.lock();
392:         !interrupts_enabled()
393:     };
394:     let restored_after_enabled = interrupts_enabled() == initially_enabled;
395: 
396:     let flags = disable_interrupts();
397:     let masked_while_already_disabled = {
398:         let _guard = lock.lock();
399:         !interrupts_enabled()
400:     };
401:     let remained_disabled_after_drop = !interrupts_enabled();
402:     restore_interrupts(flags);
403: 
404:     initially_enabled
405:         && masked_while_held
406:         && restored_after_enabled
407:         && masked_while_already_disabled
408:         && remained_disabled_after_drop
409: }
