423:     let mut runtime =
424:         KernelThreadRuntime::new(ticks).map_err(|_| "preemption scheduler setup failed")?;
425:     let runtime_pointer = core::ptr::addr_of_mut!(runtime);
426:     let ticks_pointer = ticks as *const AtomicTickCounter as usize;
