464:     // Both workers busy-wait without yielding. Worker B can start only after a
465:     // PIT interrupt preempts worker A. Worker A also checks that its live XMM0
466:     // value survives the interrupt handler and another thread's execution.
467:     unsafe { KernelThreadRuntime::run_from_raw(runtime_pointer) };
468:     let passed = PREEMPTION_A_STARTED.load(Ordering::Acquire) == 1
469:         && PREEMPTION_B_STARTED.load(Ordering::Acquire) == 1
470:         && PREEMPTION_TEST_FAILED.load(Ordering::Acquire) == 0
471:         && PREEMPTION_FPU_FAILED.load(Ordering::Acquire) == 0
