484: extern "C" fn non_yielding_preemption_worker_a(_runtime: *mut (), ticks_pointer: usize) {
485:     PREEMPTION_A_STARTED.store(1, Ordering::Release);
486:     let ticks = unsafe { &*(ticks_pointer as *const AtomicTickCounter) };
487:     let deadline = ticks.ticks().saturating_add(PREEMPTION_TEST_TICK_BUDGET);
488:     unsafe {
489:         asm!(
490:             "movdqu xmm0, xmmword ptr [{pattern}]",
491:             pattern = in(reg) PREEMPTION_PATTERN_A.as_ptr(),
492:             out("xmm0") _,
493:             options(readonly, nostack, preserves_flags),
494:         );
495:     }
496:     while PREEMPTION_B_STARTED.load(Ordering::Acquire) == 0 {
497:         if ticks.ticks() >= deadline {
498:             PREEMPTION_TEST_FAILED.store(1, Ordering::Release);
499:             break;
500:         }
501:         spin_loop();
502:     }
503:     let mut saved_state = core::mem::MaybeUninit::<FxSaveArea>::uninit();
504:     // SAFETY: `FxSaveArea` is 16-byte aligned and exactly 512 bytes; FXSAVE
505:     // writes the complete legacy x87/SSE state image before it is inspected.
506:     unsafe {
507:         asm!(
508:             "fxsave64 [{state}]",
509:             state = in(reg) saved_state.as_mut_ptr(),
510:             options(nostack),
511:         );
512:     }
513:     // SAFETY: The preceding FXSAVE initialized every byte of the state image.
514:     let saved_state = unsafe { saved_state.assume_init() };
515:     if saved_state.0[160..176] != PREEMPTION_PATTERN_A {
516:         PREEMPTION_FPU_FAILED.store(1, Ordering::Release);
517:     }
518: }
