816: #[cfg(feature = "probe-kernel-threads")]
817: fn wait_for_event(runtime_pointer: *mut ()) -> bool {
818:     // SAFETY: This is an ordinary cooperative thread, never an IRQ handler.
819:     unsafe { block_current(runtime_pointer.cast(), None) }
820: }
