822: #[cfg(feature = "probe-kernel-threads")]
823: fn sleep_for_ticks(runtime_pointer: *mut (), delay: u64) -> bool {
824:     if delay == 0 {
825:         return true;
826:     }
827:     // SAFETY: The runtime pointer is restored from this thread's initial context;
828:     // the runtime remains alive until every thread has exited and been reaped.
829:     unsafe { block_current(runtime_pointer.cast(), Some(delay)) }
830: }
