832: #[cfg(feature = "probe-kernel-threads")]
833: fn wake_event(runtime_pointer: *mut ()) -> bool {
834:     let flags = disable_interrupts();
835:     // SAFETY: IF is clear and only the current cooperative thread mutates policy.
836:     let result = unsafe {
837:         let runtime = &mut *runtime_pointer.cast::<KernelThreadRuntime>();
838:         runtime.policy.wake_one(runtime.event_queue).is_ok()
839:     };
840:     restore_interrupts(flags);
841:     result
842: }
