844: #[cfg(feature = "probe-kernel-threads")]
845: fn yield_current(runtime_pointer: *mut ()) {
846:     let flags = disable_interrupts();
847:     let switch = unsafe {
848:         let runtime = &mut *runtime_pointer.cast::<KernelThreadRuntime>();
849:         runtime.wake_ready_events();
850:         let Some(current) = runtime.policy.current() else {
851:             restore_interrupts(flags);
852:             return;
853:         };
854:         let old_context = runtime.current_context;
855:         let next = match runtime.policy.yield_current() {
856:             Ok(next) => next,
857:             Err(_) => {
858:                 THREAD_TEST_TRACE.store(99, Ordering::Release);
859:                 restore_interrupts(flags);
860:                 return;
861:             }
862:         };
863:         let next_context = next.slot_index() + 1;
864:         runtime.current_context = next_context;
865:         if current == next {
866:             None
867:         } else {
868:             Some((
869:                 core::ptr::addr_of_mut!(runtime.saved_rsp[old_context]),
870:                 runtime.saved_rsp[next_context],
871:                 core::ptr::addr_of_mut!(runtime.fx_state[old_context]),
872:                 core::ptr::addr_of_mut!(runtime.fx_state[next_context]),
873:             ))
874:         }
875:     };
876:     if let Some((old_rsp, new_rsp, old_fx_state, new_fx_state)) = switch {
877:         // SAFETY: The selected contexts are same-CPU kernel stacks, and the
878:         // temporary scheduler borrows end before switching their saved FPU state.
879:         unsafe {
880:             rustix_arch_context_switch(old_rsp, new_rsp as *mut usize, old_fx_state, new_fx_state)
881:         };
882:     }
883:     restore_interrupts(flags);
884: }
