886: unsafe fn block_current(runtime_pointer: *mut KernelThreadRuntime, delay: Option<u64>) -> bool {
887:     let flags = disable_interrupts();
888:     let switch = {
889:         // SAFETY: Called from one cooperative thread with IF clear; the state
890:         // references are scoped entirely before the context switch.
891:         let runtime = unsafe { &mut *runtime_pointer };
892:         let input_event = runtime.wake_ready_events();
893:         if delay.is_none() && runtime.input_events_enabled && input_event {
894:             restore_interrupts(flags);
895:             return true;
896:         }
897:         let Some(current) = runtime.policy.current() else {
898:             restore_interrupts(flags);
899:             return false;
900:         };
901:         let slot = current.slot_index();
902:         let queue = if let Some(delay) = delay {
903:             let deadline = runtime.ticks.ticks().saturating_add(delay);
904:             runtime.deadlines[slot] = Some(deadline);
905:             runtime.timer_queues[slot]
906:         } else {
907:             runtime.event_queue
908:         };
909:         let next = match runtime.policy.sleep_current(queue) {
910:             Ok(next) => next,
911:             Err(_) => {
912:                 runtime.deadlines[slot] = None;
913:                 restore_interrupts(flags);
914:                 return false;
915:             }
916:         };
917:         let next_context = next.map_or(0, |thread| thread.slot_index() + 1);
918:         let old_context = runtime.current_context;
919:         runtime.current_context = next_context;
920:         Some((
921:             core::ptr::addr_of_mut!(runtime.saved_rsp[old_context]),
922:             runtime.saved_rsp[next_context],
923:             core::ptr::addr_of_mut!(runtime.fx_state[old_context]),
924:             core::ptr::addr_of_mut!(runtime.fx_state[next_context]),
925:         ))
926:     };
927:     if let Some((old_rsp, new_rsp, old_fx_state, new_fx_state)) = switch {
928:         // SAFETY: The current thread is blocked and cannot run until a later
929:         // wake; both stack and FXSAVE areas remain live in the runtime.
930:         unsafe {
931:             rustix_arch_context_switch(old_rsp, new_rsp as *mut usize, old_fx_state, new_fx_state)
932:         };
933:     }
934:     restore_interrupts(flags);
935:     true
936: }
