938: unsafe fn exit_current(runtime_pointer: *mut KernelThreadRuntime) -> ! {
939:     let flags = disable_interrupts();
940:     let (old_rsp, new_rsp, old_fx_state, new_fx_state) = {
941:         // SAFETY: This is the current thread's normal return path, with IF clear.
942:         let runtime = unsafe { &mut *runtime_pointer };
943:         runtime.wake_ready_events();
944:         let old_context = runtime.current_context;
945:         match runtime.policy.exit_current() {
946:             Ok(next) => {
947:                 let next_context = next.map_or(0, |thread| thread.slot_index() + 1);
948:                 runtime.current_context = next_context;
949:                 (
950:                     core::ptr::addr_of_mut!(runtime.saved_rsp[old_context]),
951:                     runtime.saved_rsp[next_context],
952:                     core::ptr::addr_of_mut!(runtime.fx_state[old_context]),
953:                     core::ptr::addr_of_mut!(runtime.fx_state[next_context]),
954:                 )
955:             }
956:             Err(_) => halt_on_stack_cleanup_failure(),
957:         }
958:     };
959:     // SAFETY: The exited context is never dispatched again; the target is a
960:     // different ready thread or the retained bootstrap stack.
961:     unsafe {
962:         rustix_arch_context_switch(old_rsp, new_rsp as *mut usize, old_fx_state, new_fx_state)
963:     };
964:     restore_interrupts(flags);
965:     halt_on_stack_cleanup_failure()
966: }
