968: fn disable_interrupts() -> u64 {
969:     let flags: u64;
970:     // SAFETY: Bootstrap and cooperative threads execute at CPL 0; RFLAGS is
971:     // saved before CLI and the stack operation is balanced.
972:     unsafe { asm!("pushfq", "pop {}", "cli", out(reg) flags) };
973:     flags
974: }
975: 
976: fn restore_interrupts(flags: u64) {
977:     if flags & (1 << 9) != 0 {
978:         // SAFETY: The caller only restores the prior IF state after its critical
979:         // section and after the selected stack/context is fully established.
980:         unsafe { asm!("sti") };
981:     }
982: }
