984: unsafe fn rustix_arch_context_switch(
985:     old_rsp: *mut usize,
986:     new_rsp: *mut usize,
987:     old_fx_state: *mut FxSaveArea,
988:     new_fx_state: *mut FxSaveArea,
989: ) {
990:     // SAFETY: The runtime maintains valid saved stack frames and aligned state
991:     // areas. Callers hold IF clear; publish the new area before it can receive IRQs.
992:     unsafe { publish_fx_state(new_fx_state) };
993:     // SAFETY: The context switch saves the current x87/SSE state and restores the
994:     // target context's initialized/saved FXSAVE image.
995:     unsafe {
996:         crate::arch::x86_64::context::context_switch(
997:             old_rsp,
998:             new_rsp,
999:             old_fx_state.cast(),
1000:             new_fx_state.cast(),
1001:         )
1002:     };
1003: }
1004: 
1005: unsafe fn rustix_arch_context_switch_from_irq(
1006:     old_rsp: *mut usize,
1007:     new_rsp: *mut usize,
1008:     new_fx_state: *mut FxSaveArea,
1009: ) {
1010:     // SAFETY: The IRQ stub already saved the interrupted task's FPU state before
1011:     // entering Rust. Update the return-path target before switching away.
1012:     unsafe { publish_fx_state(new_fx_state) };
1013:     // SAFETY: This is called only from the configured timer IRQ handler with IF
1014:     // clear; the target area's state is initialized and 16-byte aligned.
1015:     unsafe {
1016:         crate::arch::x86_64::context::context_switch_from_irq(old_rsp, new_rsp, new_fx_state.cast())
1017:     };
1018: }
