1020: unsafe fn publish_fx_state(state: *mut FxSaveArea) {
1021:     // SAFETY: The single-vCPU runtime calls this only with IF clear; IRQ assembly
1022:     // reads the pointer only while executing on that same CPU.
1023:     unsafe { ACTIVE_FX_STATE_POINTER = state };
1024: }
1025: 
1026: unsafe fn save_bootstrap_fx_state() {
1027:     let state = core::ptr::addr_of_mut!(BOOTSTRAP_FX_STATE);
1028:     // SAFETY: FXSAVE is enabled during boot, `state` is 16-byte aligned, and the
1029:     // caller has IF clear while the last kernel thread returns to the bootstrap.
1030:     unsafe { asm!("fxsave64 [{}]", in(reg) state, options(nostack)) };
1031:     // SAFETY: Interrupts remain disabled until the saved bootstrap area is active.
1032:     unsafe { publish_fx_state(state) };
1033: }
