381:     fn interrupts_enabled() -> bool {
382:         let flags: u64;
383:         // SAFETY: Reading RFLAGS is non-mutating in the CPL 0 QEMU probe.
384:         unsafe { asm!("pushfq", "pop {}", out(reg) flags) };
385:         flags & (1 << 9) != 0
