441:             candidate,
442:             allocator,
443:             cpu_info,
444:             runtime_pointer,
445:             non_yielding_preemption_worker_b,
446:             ticks_pointer,
447:         )
448:     } else {
449:         Err("first preemption worker stack setup failed")
450:     };
451:     restore_interrupts(flags);
452: 
453:     if first.is_err() || second.is_err() {
454:         cancel_unstarted_threads(&mut runtime);
455:         let flags = disable_interrupts();
456:         reap_exited_stacks(&mut runtime, candidate, allocator);
457:         restore_interrupts(flags);
458:         return Err(first
459:             .err()
460:             .or(second.err())
461:             .unwrap_or("preemption worker setup failed"));
462:     }
463: 
464:     // Both workers busy-wait without yielding. Worker B can start only after a
465:     // PIT interrupt preempts worker A. Worker A also checks that its live XMM0
466:     // value survives the interrupt handler and another thread's execution.
467:     unsafe { KernelThreadRuntime::run_from_raw(runtime_pointer) };
468:     let passed = PREEMPTION_A_STARTED.load(Ordering::Acquire) == 1
469:         && PREEMPTION_B_STARTED.load(Ordering::Acquire) == 1
470:         && PREEMPTION_TEST_FAILED.load(Ordering::Acquire) == 0
471:         && PREEMPTION_FPU_FAILED.load(Ordering::Acquire) == 0
472:         && runtime.all_threads_exited();
473:     let flags = disable_interrupts();
474:     reap_exited_stacks(&mut runtime, candidate, allocator);
475:     restore_interrupts(flags);
476:     if !passed {
477:         return Err("timer did not preempt a non-yielding thread within the tick budget");
478:     }
479:     kprintln!("timer preemption path passed: non-yielding workers and FPU state survived");
480:     Ok(())
481: }
