520: #[cfg(feature = "probe-kernel-threads")]
521: extern "C" fn non_yielding_preemption_worker_b(_runtime: *mut (), _ticks_pointer: usize) {
522:     unsafe {
523:         asm!(
524:             "movdqu xmm0, xmmword ptr [{pattern}]",
525:             pattern = in(reg) PREEMPTION_PATTERN_B.as_ptr(),
526:             out("xmm0") _,
527:             options(readonly, nostack, preserves_flags),
528:         );
529:     }
530:     PREEMPTION_B_STARTED.store(1, Ordering::Release);
531: }
