533: fn spawn_thread<M: CandidatePageTableMemory>(
534:     runtime: &mut KernelThreadRuntime,
535:     candidate: &mut CandidatePageTables<'_, M>,
536:     allocator: &mut FrameAllocator,
537:     cpu_info: &crate::arch::x86_64::cpu::CpuInfo,
538:     runtime_pointer: *mut KernelThreadRuntime,
539:     entry: ThreadEntry,
540:     argument: usize,
541: ) -> Result<ThreadId, &'static str> {
542:     let slot = runtime
543:         .thread_ids
544:         .iter()
545:         .position(Option::is_none)
546:         .ok_or("thread capacity exhausted")?;
547:     let region_start = THREAD_STACK_VIRTUAL_BASE
548:         .checked_add(
549:             (slot as u64)
550:                 .checked_mul(THREAD_STACK_STRIDE)
551:                 .ok_or("stack VA overflow")?,
552:         )
553:         .ok_or("stack VA overflow")?;
554:     let stack_start = region_start
555:         .checked_add(PAGE_SIZE)
556:         .ok_or("stack VA overflow")?;
557: 
558:     for page in 0..=THREAD_STACK_PAGES {
559:         let address = region_start + page as u64 * PAGE_SIZE;
560:         if !matches!(
561:             candidate.walk(address),
562:             Ok(PageWalkOutcome::NotPresent { .. })
563:         ) {
564:             return Err("thread guard or stack VA is already mapped");
565:         }
566:     }
567: 
568:     let physical_width = cpu_info
569:         .physical_address_bits
570:         .ok_or("physical width unavailable")?;
571:     let pat = PatLayout::from_msr_value(cpu_info.pat_msr_value.ok_or("PAT unavailable")?)
572:         .map_err(|_| "PAT state invalid")?;
573:     let mtrrs = match &cpu_info.mtrr {
574:         MtrrState::Captured(registers) => registers
575:             .validated_layout(physical_width)
576:             .map_err(|_| "MTRR state invalid")?,
577:         _ => return Err("MTRR state unavailable"),
578:     };
579:     let permissions = PagePermissions {
580:         writable: true,
581:         executable: false,
582:         user_accessible: false,
583:     };
584:     let mut mapped_pages = 0usize;
585:     for page in 0..THREAD_STACK_PAGES {
586:         let virtual_address = stack_start + page as u64 * PAGE_SIZE;
587:         let frame = allocator.allocate().ok_or_else(|| {
588:             rollback_stack(candidate, allocator, stack_start, mapped_pages);
589:             "physical frames exhausted for thread stack"
590:         })?;
591:         let mapping = match validate_mapping_range(
592:             virtual_address,
593:             frame.address(),
594:             PAGE_SIZE,
595:             permissions,
596:             Some(physical_width),
597:             cpu_info.active_linear_address_bits,
598:         ) {
599:             Ok(mapping) => mapping,
600:             Err(_) => {
601:                 deallocate_or_halt(allocator, frame);
602:                 rollback_stack(candidate, allocator, stack_start, mapped_pages);
603:                 return Err("thread stack mapping rejected");
604:             }
605:         };
606:         let attributes = match mapping.select_cache_attributes(
607:             CachePolicy::WriteBack,
608:             pat,
609:             &mtrrs,
610:             cpu_info.normal_caching,
611:         ) {
612:             Ok(attributes) if attributes.effective_type() == EffectiveMemoryType::WriteBack => {
613:                 attributes
614:             }
615:             _ => {
616:                 deallocate_or_halt(allocator, frame);
617:                 rollback_stack(candidate, allocator, stack_start, mapped_pages);
618:                 return Err("thread stack has no uniform write-back policy");
619:             }
620:         };
621:         // SAFETY: The active root is current on this single CPU; IF is clear
622:         // throughout stack setup, and each mapping uses an allocator-owned frame.
623:         if let Err(failure) =
624:             unsafe { candidate.map_owned_page_active(allocator, frame, mapping, attributes) }
625:         {
626:             deallocate_or_halt(allocator, failure.frame);
627:             rollback_stack(candidate, allocator, stack_start, mapped_pages);
628:             return Err("thread stack mapping failed");
629:         }
630:         match candidate.walk(virtual_address) {
631:             Ok(PageWalkOutcome::Mapped(translation))
632:                 if translation.permissions == permissions
633:                     && translation.pat_index == attributes.pat_index() => {}
634:             _ => {
635:                 rollback_stack(candidate, allocator, stack_start, mapped_pages + 1);
636:                 return Err("thread stack page-table verification failed");
637:             }
638:         }
639:         mapped_pages += 1;
640:     }
641: 
642:     let stack_top = stack_start + THREAD_STACK_PAGES as u64 * PAGE_SIZE;
643:     let frame_word_count = 16;
644:     let frame_words = unsafe {
645:         core::slice::from_raw_parts_mut(
646:             (stack_top as *mut usize).sub(frame_word_count),
647:             frame_word_count,
648:         )
649:     };
650:     let registers = [0, slot, runtime_pointer as usize, 0, 0, 0];
651:     let saved_rsp = initialize_thread_context_stack(
652:         frame_words,
653:         registers,
654:         kernel_thread_trampoline as *const () as usize,
655:     );
656:     let Some(saved_rsp) = saved_rsp else {
657:         rollback_stack(candidate, allocator, stack_start, mapped_pages);
658:         return Err("thread initial context frame did not fit");
659:     };
660:     let thread = match runtime.policy.create_thread() {
661:         Ok(thread) if thread.slot_index() == slot => thread,
662:         Ok(_) => {
663:             rollback_stack(candidate, allocator, stack_start, mapped_pages);
664:             return Err("scheduler slot and stack slot diverged");
665:         }
666:         Err(_) => {
667:             rollback_stack(candidate, allocator, stack_start, mapped_pages);
668:             return Err("scheduler thread capacity exhausted");
669:         }
670:     };
671:     runtime.thread_ids[slot] = Some(thread);
672:     runtime.stack_virtual_starts[slot] = Some(stack_start);
673:     runtime.entries[slot] = Some(entry);
674:     runtime.arguments[slot] = argument;
675:     runtime.saved_rsp[slot + 1] = saved_rsp;
676:     Ok(thread)
677: }
678: 
679: fn rollback_stack<M: CandidatePageTableMemory>(
680:     candidate: &mut CandidatePageTables<'_, M>,
681:     allocator: &mut FrameAllocator,
682:     stack_start: u64,
683:     mapped_pages: usize,
684: ) {
685:     for page in (0..mapped_pages).rev() {
686:         let virtual_address = stack_start + page as u64 * PAGE_SIZE;
687:         // SAFETY: Stack setup keeps IF clear and this candidate is the active
688:         // root; the frame is not returned until `invlpg` completes.
689:         let frame = unsafe { candidate.unmap_owned_page_active(virtual_address) }
690:             .unwrap_or_else(|_| halt_on_stack_cleanup_failure());
691:         deallocate_or_halt(allocator, frame);
692:     }
693: }
694: 
695: fn reap_exited_stacks<M: CandidatePageTableMemory>(
696:     runtime: &mut KernelThreadRuntime,
697:     candidate: &mut CandidatePageTables<'_, M>,
698:     allocator: &mut FrameAllocator,
699: ) {
700:     for slot in 0..MAX_THREADS {
701:         let Some(thread) = runtime.thread_ids[slot] else {
702:             continue;
703:         };
704:         if runtime.policy.state(thread) != Ok(ThreadState::Exited) {
705:             continue;
706:         }
707:         let stack_start =
708:             runtime.stack_virtual_starts[slot].unwrap_or_else(|| halt_on_stack_cleanup_failure());
709:         rollback_stack(candidate, allocator, stack_start, THREAD_STACK_PAGES);
710:         runtime
711:             .policy
712:             .reap(thread)
713:             .unwrap_or_else(|_| halt_on_stack_cleanup_failure());
714:         runtime.thread_ids[slot] = None;
715:         runtime.stack_virtual_starts[slot] = None;
716:         runtime.entries[slot] = None;
717:         runtime.arguments[slot] = 0;
718:         runtime.deadlines[slot] = None;
719:     }
720: }
721: 
722: #[cfg(feature = "probe-kernel-threads")]
723: fn cancel_unstarted_threads(runtime: &mut KernelThreadRuntime) {
724:     loop {
725:         match runtime.policy.dispatch() {
726:             Ok(Some(_)) => {
727:                 if runtime.policy.exit_current().is_err() {
728:                     halt_on_stack_cleanup_failure();
729:                 }
730:             }
731:             Ok(None) => return,
732:             Err(_) => halt_on_stack_cleanup_failure(),
733:         }
734:     }
735: }
736: 
737: fn deallocate_or_halt(allocator: &mut FrameAllocator, frame: Frame) {
738:     if let Err(failure) = allocator.deallocate(frame) {
739:         kprintln!("thread stack frame release failed: {:?}", failure.error);
740:         halt_on_stack_cleanup_failure();
741:     }
742: }
743: 
744: fn halt_on_stack_cleanup_failure() -> ! {
745:     loop {
746:         // SAFETY: Losing stack-frame ownership is fatal; stop without touching
747:         // any potentially inconsistent scheduler or allocator state.
748:         unsafe { asm!("cli; hlt", options(nomem, nostack)) };
749:     }
750: }
751: 
752: extern "C" fn kernel_thread_trampoline() -> ! {
753:     let runtime_pointer: *mut KernelThreadRuntime;
754:     let slot: usize;
755:     // SAFETY: The initial stack frame restores the runtime pointer in R13 and
756:     // the generation-checked policy slot index in R14 before this entry.
757:     unsafe {
758:         asm!("mov {}, r13", out(reg) runtime_pointer, options(nomem, nostack, preserves_flags));
759:         asm!("mov {}, r14", out(reg) slot, options(nomem, nostack, preserves_flags));
760:     }
761:     let (entry, argument) = {
762:         // SAFETY: The runtime is live on the retained bootstrap stack and the
763:         // selected slot was initialized before its context became dispatchable.
764:         let runtime = unsafe { &*runtime_pointer };
765:         let entry = runtime.entries[slot].unwrap_or_else(|| halt_on_stack_cleanup_failure());
766:         (entry, runtime.arguments[slot])
767:     };
768:     // New cooperative contexts start with IF clear. Enable the already-verified
769:     // timer route only after their descriptor and runtime state are available.
770:     // SAFETY: The scheduler installs no thread until the caller has configured
771:     // the timer and registered its bounded non-scheduling handler.
772:     unsafe { asm!("sti") };
773:     entry(runtime_pointer.cast(), argument);
774:     // SAFETY: This thread's entry returned normally; mark it exited and switch
775:     // away before its stack can be reclaimed by the bootstrap context.
776:     unsafe { exit_current(runtime_pointer) }
777: }
