779: #[cfg(feature = "probe-kernel-threads")]
780: extern "C" fn waiter_thread(runtime: *mut (), _argument: usize) {
781:     THREAD_TEST_TRACE.store(1, Ordering::Release);
782:     if !wait_for_event(runtime) || THREAD_TEST_TRACE.load(Ordering::Acquire) != 2 {
783:         THREAD_TEST_TRACE.store(99, Ordering::Release);
784:         return;
785:     }
786:     THREAD_TEST_TRACE.store(3, Ordering::Release);
787:     if !sleep_for_ticks(runtime, 2) || THREAD_TEST_TRACE.load(Ordering::Acquire) != 4 {
788:         THREAD_TEST_TRACE.store(99, Ordering::Release);
789:         return;
790:     }
791:     THREAD_TEST_TRACE.store(5, Ordering::Release);
792: }
793: 
794: #[cfg(feature = "probe-kernel-threads")]
795: extern "C" fn signaler_thread(runtime: *mut (), _argument: usize) {
796:     if THREAD_TEST_TRACE.load(Ordering::Acquire) != 1 {
797:         THREAD_TEST_TRACE.store(99, Ordering::Release);
798:         return;
799:     }
800:     THREAD_TEST_TRACE.store(2, Ordering::Release);
801:     if !wake_event(runtime) {
802:         THREAD_TEST_TRACE.store(99, Ordering::Release);
803:         return;
804:     }
805:     yield_current(runtime);
806:     if THREAD_TEST_TRACE.load(Ordering::Acquire) != 3 {
807:         THREAD_TEST_TRACE.store(99, Ordering::Release);
808:         return;
809:     }
810:     THREAD_TEST_TRACE.store(4, Ordering::Release);
811:     while THREAD_TEST_TRACE.load(Ordering::Acquire) != 5 {
812:         yield_current(runtime);
813:     }
814: }
