816: #[cfg(feature = "probe-kernel-threads")]
817: fn wait_for_event(runtime_pointer: *mut ()) -> bool {
818:     // SAFETY: This is an ordinary cooperative thread, never an IRQ handler.
819:     unsafe { block_current(runtime_pointer.cast(), None) }
820: }
821: 
822: #[cfg(feature = "probe-kernel-threads")]
823: fn sleep_for_ticks(runtime_pointer: *mut (), delay: u64) -> bool {
824:     if delay == 0 {
825:         return true;
826:     }
827:     // SAFETY: The runtime pointer is restored from this thread's initial context;
828:     // the runtime remains alive until every thread has exited and been reaped.
829:     unsafe { block_current(runtime_pointer.cast(), Some(delay)) }
830: }
831: 
832: #[cfg(feature = "probe-kernel-threads")]
833: fn wake_event(runtime_pointer: *mut ()) -> bool {
834:     let flags = disable_interrupts();
835:     // SAFETY: IF is clear and only the current cooperative thread mutates policy.
836:     let result = unsafe {
837:         let runtime = &mut *runtime_pointer.cast::<KernelThreadRuntime>();
838:         runtime.policy.wake_one(runtime.event_queue).is_ok()
839:     };
840:     restore_interrupts(flags);
841:     result
842: }
843: 
844: #[cfg(feature = "probe-kernel-threads")]
845: fn yield_current(runtime_pointer: *mut ()) {
846:     let flags = disable_interrupts();
847:     let switch = unsafe {
848:         let runtime = &mut *runtime_pointer.cast::<KernelThreadRuntime>();
849:         runtime.wake_ready_events();
850:         let Some(current) = runtime.policy.current() else {
851:             restore_interrupts(flags);
852:             return;
853:         };
854:         let old_context = runtime.current_context;
855:         let next = match runtime.policy.yield_current() {
856:             Ok(next) => next,
857:             Err(_) => {
858:                 THREAD_TEST_TRACE.store(99, Ordering::Release);
859:                 restore_interrupts(flags);
860:                 return;
861:             }
862:         };
863:         let next_context = next.slot_index() + 1;
864:         runtime.current_context = next_context;
865:         if current == next {
866:             None
867:         } else {
868:             Some((
869:                 core::ptr::addr_of_mut!(runtime.saved_rsp[old_context]),
870:                 runtime.saved_rsp[next_context],
871:                 core::ptr::addr_of_mut!(runtime.fx_state[old_context]),
872:                 core::ptr::addr_of_mut!(runtime.fx_state[next_context]),
873:             ))
874:         }
875:     };
876:     if let Some((old_rsp, new_rsp, old_fx_state, new_fx_state)) = switch {
877:         // SAFETY: The selected contexts are same-CPU kernel stacks, and the
878:         // temporary scheduler borrows end before switching their saved FPU state.
879:         unsafe {
880:             rustix_arch_context_switch(old_rsp, new_rsp as *mut usize, old_fx_state, new_fx_state)
881:         };
882:     }
883:     restore_interrupts(flags);
884: }
885: 
886: unsafe fn block_current(runtime_pointer: *mut KernelThreadRuntime, delay: Option<u64>) -> bool {
887:     let flags = disable_interrupts();
888:     let switch = {
889:         // SAFETY: Called from one cooperative thread with IF clear; the state
890:         // references are scoped entirely before the context switch.
891:         let runtime = unsafe { &mut *runtime_pointer };
892:         let input_event = runtime.wake_ready_events();
893:         if delay.is_none() && runtime.input_events_enabled && input_event {
894:             restore_interrupts(flags);
895:             return true;
896:         }
897:         let Some(current) = runtime.policy.current() else {
898:             restore_interrupts(flags);
899:             return false;
900:         };
901:         let slot = current.slot_index();
902:         let queue = if let Some(delay) = delay {
903:             let deadline = runtime.ticks.ticks().saturating_add(delay);
904:             runtime.deadlines[slot] = Some(deadline);
905:             runtime.timer_queues[slot]
906:         } else {
907:             runtime.event_queue
908:         };
909:         let next = match runtime.policy.sleep_current(queue) {
910:             Ok(next) => next,
911:             Err(_) => {
912:                 runtime.deadlines[slot] = None;
913:                 restore_interrupts(flags);
914:                 return false;
915:             }
916:         };
917:         let next_context = next.map_or(0, |thread| thread.slot_index() + 1);
918:         let old_context = runtime.current_context;
919:         runtime.current_context = next_context;
920:         Some((
921:             core::ptr::addr_of_mut!(runtime.saved_rsp[old_context]),
922:             runtime.saved_rsp[next_context],
923:             core::ptr::addr_of_mut!(runtime.fx_state[old_context]),
924:             core::ptr::addr_of_mut!(runtime.fx_state[next_context]),
925:         ))
926:     };
927:     if let Some((old_rsp, new_rsp, old_fx_state, new_fx_state)) = switch {
928:         // SAFETY: The current thread is blocked and cannot run until a later
929:         // wake; both stack and FXSAVE areas remain live in the runtime.
930:         unsafe {
931:             rustix_arch_context_switch(old_rsp, new_rsp as *mut usize, old_fx_state, new_fx_state)
932:         };
933:     }
934:     restore_interrupts(flags);
935:     true
936: }
937: 
938: unsafe fn exit_current(runtime_pointer: *mut KernelThreadRuntime) -> ! {
939:     let flags = disable_interrupts();
940:     let (old_rsp, new_rsp, old_fx_state, new_fx_state) = {
941:         // SAFETY: This is the current thread's normal return path, with IF clear.
942:         let runtime = unsafe { &mut *runtime_pointer };
943:         runtime.wake_ready_events();
944:         let old_context = runtime.current_context;
945:         match runtime.policy.exit_current() {
946:             Ok(next) => {
947:                 let next_context = next.map_or(0, |thread| thread.slot_index() + 1);
948:                 runtime.current_context = next_context;
949:                 (
950:                     core::ptr::addr_of_mut!(runtime.saved_rsp[old_context]),
951:                     runtime.saved_rsp[next_context],
952:                     core::ptr::addr_of_mut!(runtime.fx_state[old_context]),
953:                     core::ptr::addr_of_mut!(runtime.fx_state[next_context]),
954:                 )
955:             }
956:             Err(_) => halt_on_stack_cleanup_failure(),
957:         }
958:     };
959:     // SAFETY: The exited context is never dispatched again; the target is a
960:     // different ready thread or the retained bootstrap stack.
961:     unsafe {
962:         rustix_arch_context_switch(old_rsp, new_rsp as *mut usize, old_fx_state, new_fx_state)
963:     };
964:     restore_interrupts(flags);
965:     halt_on_stack_cleanup_failure()
966: }
967: 
968: fn disable_interrupts() -> u64 {
969:     let flags: u64;
970:     // SAFETY: Bootstrap and cooperative threads execute at CPL 0; RFLAGS is
971:     // saved before CLI and the stack operation is balanced.
972:     unsafe { asm!("pushfq", "pop {}", "cli", out(reg) flags) };
973:     flags
974: }
975: 
976: fn restore_interrupts(flags: u64) {
977:     if flags & (1 << 9) != 0 {
978:         // SAFETY: The caller only restores the prior IF state after its critical
979:         // section and after the selected stack/context is fully established.
980:         unsafe { asm!("sti") };
981:     }
982: }
983: 
984: unsafe fn rustix_arch_context_switch(
985:     old_rsp: *mut usize,
986:     new_rsp: *mut usize,
987:     old_fx_state: *mut FxSaveArea,
988:     new_fx_state: *mut FxSaveArea,
989: ) {
990:     // SAFETY: The runtime maintains valid saved stack frames and aligned state
991:     // areas. Callers hold IF clear; publish the new area before it can receive IRQs.
992:     unsafe { publish_fx_state(new_fx_state) };
993:     // SAFETY: The context switch saves the current x87/SSE state and restores the
994:     // target context's initialized/saved FXSAVE image.
995:     unsafe {
996:         crate::arch::x86_64::context::context_switch(
997:             old_rsp,
998:             new_rsp,
999:             old_fx_state.cast(),
