1035: /// Advance scheduler deadlines/events and preempt the current thread if another
1036: /// context is ready. Called only after the timer IRQ has sent APIC EOI.
1037: pub(crate) fn timer_interrupt() {
1038:     let runtime_pointer = ACTIVE_RUNTIME.load(Ordering::Acquire);
1039:     if runtime_pointer.is_null() {
1040:         return;
1041:     }
1042: 
1043:     // The interrupt gate has cleared IF. Every ordinary scheduler mutation also
1044:     // disables IF before borrowing this runtime, so the single CPU cannot observe
1045:     // a partially updated scheduler state here.
1046:     let switch = unsafe {
1047:         let runtime = &mut *runtime_pointer;
1048:         runtime.wake_ready_events();
1049:         let Some(current) = runtime.policy.current() else {
1050:             return;
1051:         };
1052:         let old_context = runtime.current_context;
1053:         if old_context != current.slot_index() + 1 {
1054:             halt_on_stack_cleanup_failure();
1055:         }
1056:         let next = runtime
1057:             .policy
1058:             .preempt_current()
1059:             .unwrap_or_else(|_| halt_on_stack_cleanup_failure());
1060:         let next_context = next.slot_index() + 1;
1061:         runtime.current_context = next_context;
1062:         if next == current {
1063:             None
1064:         } else {
1065:             Some((
1066:                 core::ptr::addr_of_mut!(runtime.saved_rsp[old_context]),
1067:                 runtime.saved_rsp[next_context],
1068:                 core::ptr::addr_of_mut!(runtime.fx_state[next_context]),
1069:             ))
1070:         }
1071:     };
1072:     if let Some((old_rsp, new_rsp, new_fx_state)) = switch {
1073:         // SAFETY: The interrupted context's FXSAVE image was written by the IRQ
1074:         // stub before Rust ran. This suspends the handler stack and restores the
1075:         // selected context; the interrupted thread later resumes through IRETQ.
1076:         unsafe {
1077:             rustix_arch_context_switch_from_irq(old_rsp, new_rsp as *mut usize, new_fx_state)
1078:         };
1079:     }
