314: /// Program PIT channel 0 and configure the resolved ISA IRQ0 I/O APIC entry.
315: ///
316: /// The route is installed masked. A divisor of zero uses the 8254's encoding
317: /// for 65,536 input clocks; values 1 through 65,535 are used literally.
318: ///
319: /// # Safety
320: /// Must execute at CPL 0 on the bootstrap processor with maskable interrupts
321: /// disabled, after successful [`initialize`]. No other code may concurrently
322: /// access the PIT or I/O APIC. The mappings supplied to `initialize` must remain
323: /// valid and retain their documented permissions and cache type.
324: pub unsafe fn configure_pit_timer(vector: u8, divisor: u16) -> Result<(), ApicError> {
325:     if !interrupts_are_disabled() {
326:         return Err(ApicError::InterruptsEnabled);
327:     }
328:     if !INITIALIZED.load(Ordering::Acquire) {
329:         return Err(ApicError::NotInitialized);
330:     }
331:     if vector < 32 || vector == APIC_SPURIOUS_VECTOR {
332:         return Err(ApicError::InvalidVector);
333:     }
