340:     let destination = BOOTSTRAP_APIC_ID.load(Ordering::Relaxed);
341:     let attributes = TIMER_ROUTE_ATTRIBUTES.load(Ordering::Relaxed);
342:     let polarity = if attributes & 1 != 0 {
343:         InterruptPolarity::ActiveLow
344:     } else {
345:         InterruptPolarity::ActiveHigh
346:     };
347:     let trigger = if attributes & 2 != 0 {
348:         InterruptTrigger::Level
349:     } else {
350:         InterruptTrigger::Edge
