33: const APIC_SPURIOUS_VECTOR: u8 = 0xff;
34: 
35: const IO_APIC_ID: u8 = 0x00;
36: const IO_APIC_VERSION: u8 = 0x01;
37: const IO_APIC_REDIR_BASE: u8 = 0x10;
38: const IO_APIC_REDIR_MAX: u8 = 0xfe;
39: const IO_APIC_REDIR_MASKED: u32 = 1 << 16;
40: const IO_APIC_MAX_REDIRECTIONS: u8 = 120;
41: 
42: const PIC1_DATA: u16 = 0x21;
43: const PIC2_DATA: u16 = 0xa1;
44: const PIT_CHANNEL_0: u16 = 0x40;
45: const PIT_COMMAND: u16 = 0x43;
46: const PIT_RATE_GENERATOR_LOHI: u8 = 0x34;
