48: static INITIALIZED: AtomicBool = AtomicBool::new(false);
49: static TIMER_CONFIGURED: AtomicBool = AtomicBool::new(false);
50: static LOCAL_APIC_VIRTUAL: AtomicU64 = AtomicU64::new(0);
51: static IO_APIC_VIRTUAL: AtomicU64 = AtomicU64::new(0);
52: static TIMER_LOW_REGISTER: AtomicU8 = AtomicU8::new(0);
53: static TIMER_ROUTE_ATTRIBUTES: AtomicU8 = AtomicU8::new(0);
54: static BOOTSTRAP_APIC_ID: AtomicU8 = AtomicU8::new(0);
55: static IO_APIC_GSI_BASE: AtomicU32 = AtomicU32::new(0);
56: static IO_APIC_MAX_REDIRECTION: AtomicU8 = AtomicU8::new(0);
57: static ISA_ROUTE_LOW_REGISTERS: [AtomicU8; 16] = [const { AtomicU8::new(0) }; 16];
