59: /// Errors reported while validating or configuring the bootstrap APIC route.
60: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
61: pub enum ApicError {
62:     InterruptsEnabled,
63:     AlreadyInitialized,
64:     ApicFeatureUnavailable,
65:     X2ApicMode,
66:     LocalApicAddressMismatch,
67:     InvalidMappedAddress,
68:     MissingBootstrapApic,
69:     BootstrapApicIdMismatch,
70:     MissingOrMultipleIoApics,
71:     IoApicAddressMismatch,
72:     IoApicIdMismatch,
73:     InvalidIoApicVersion,
74:     GsiRangeOverflow,
75:     TimerGsiOutOfRange,
76:     InvalidVector,
77:     NotInitialized,
78:     TimerNotConfigured,
79:     InvalidIsaIrq,
80:     IsaRouteOutOfRange,
81:     IsaRouteNotConfigured,
82: }
