84: /// Initialize the local xAPIC and the single MADT-described I/O APIC.
85: ///
86: /// This masks both legacy PICs and all I/O APIC redirection entries, masks the
87: /// local APIC LVT entries, then enables the local APIC's software interface.
88: /// The ISA IRQ0 route is resolved and range-checked here, but remains masked.
89: ///
90: /// # Safety
91: /// Must execute at CPL 0 on the bootstrap processor with maskable interrupts
92: /// disabled. `local_apic_virtual` and `io_apic_virtual` must be page-aligned
93: /// virtual addresses of valid, writable, supervisor, NX, UC mappings of the
94: /// complete physical pages identified by `madt`. Those mappings must remain
95: /// valid for all subsequent calls. No other CPU or code may access or reprogram
96: /// these controllers concurrently. `madt` must be a validated ACPI MADT.
97: pub unsafe fn initialize(
98:     madt: &Madt,
99:     local_apic_virtual: u64,
100:     io_apic_virtual: u64,
101:     bootstrap_apic_id: u8,
102: ) -> Result<(), ApicError> {
103:     if !interrupts_are_disabled() {
104:         return Err(ApicError::InterruptsEnabled);
105:     }
106:     if INITIALIZED.load(Ordering::Acquire) {
107:         return Err(ApicError::AlreadyInitialized);
108:     }
109: 
110:     TIMER_CONFIGURED.store(false, Ordering::Relaxed);
111:     IO_APIC_GSI_BASE.store(0, Ordering::Relaxed);
112:     IO_APIC_MAX_REDIRECTION.store(0, Ordering::Relaxed);
113:     for route in &ISA_ROUTE_LOW_REGISTERS {
114:         route.store(0, Ordering::Relaxed);
115:     }
116:     LOCAL_APIC_VIRTUAL.store(0, Ordering::Relaxed);
117:     IO_APIC_VIRTUAL.store(0, Ordering::Relaxed);
118:     TIMER_LOW_REGISTER.store(0, Ordering::Relaxed);
119: 
120:     // Fail closed for legacy interrupt delivery before inspecting the APICs.
121:     // SAFETY: The caller executes at CPL 0 and the standard PIC data ports are
122:     // valid; writing 0xff masks every 8259 input.
123:     unsafe {
124:         io::write_u8(PIC1_DATA, 0xff);
125:         io::write_u8(PIC2_DATA, 0xff);
126:     }
127: 
128:     if __cpuid(1).edx & CPUID_APIC_FEATURE == 0 {
129:         return Err(ApicError::ApicFeatureUnavailable);
130:     }
131:     validate_mapped_page(local_apic_virtual)?;
132:     validate_mapped_page(io_apic_virtual)?;
133: 
134:     let mut io_apics = madt.io_apics();
135:     let io_apic = io_apics.next().ok_or(ApicError::MissingOrMultipleIoApics)?;
136:     if io_apics.next().is_some() {
137:         return Err(ApicError::MissingOrMultipleIoApics);
138:     }
139:     if io_apic.physical_address == 0 || io_apic.physical_address & 0xfff != 0 {
140:         return Err(ApicError::IoApicAddressMismatch);
141:     }
142:     if madt.local_apic_address & 0xfff != 0
143:         || madt.local_apic_address & !APIC_BASE_ADDRESS_MASK != 0
144:     {
145:         return Err(ApicError::LocalApicAddressMismatch);
146:     }
147:     if !madt
148:         .local_apics()
149:         .any(|cpu| cpu.apic_id == bootstrap_apic_id && cpu.flags & 1 != 0)
150:     {
151:         return Err(ApicError::MissingBootstrapApic);
152:     }
153: 
154:     // SAFETY: IA32_APIC_BASE is an architectural x86_64 MSR, and the CPUID APIC
155:     // feature check above confirms the APIC facility. CPL 0 is required.
156:     let apic_base = unsafe { read_msr(IA32_APIC_BASE) };
157:     if apic_base & APIC_BASE_X2APIC != 0 {
158:         return Err(ApicError::X2ApicMode);
159:     }
160:     if apic_base & APIC_BASE_ADDRESS_MASK != madt.local_apic_address {
161:         return Err(ApicError::LocalApicAddressMismatch);
162:     }
163: 
164:     // Enable the xAPIC global interface without changing its physical base.
165:     // SAFETY: Same architectural MSR/CPL invariants as the preceding read.
166:     unsafe { write_msr(IA32_APIC_BASE, apic_base | APIC_BASE_GLOBAL_ENABLE) };
167: 
168:     // SAFETY: The caller guarantees a live mapped APIC page, and the selected
169:     // offsets are aligned registers within the 4 KiB mapping.
170:     unsafe {
171:         write_local(local_apic_virtual, APIC_SVR, 0);
172:         mask_local_apic_lvt_entries(local_apic_virtual);
173:         write_local(local_apic_virtual, APIC_TPR, 0);
174:     }
175: 
176:     let io_version = unsafe { io_apic_read(io_apic_virtual, IO_APIC_VERSION) };
177:     let max_redirection_index = ((io_version >> 16) & 0xff) as u8;
178:     if max_redirection_index >= IO_APIC_MAX_REDIRECTIONS
179:         || redirection_registers(max_redirection_index, max_redirection_index).is_none()
180:     {
181:         return Err(ApicError::InvalidIoApicVersion);
182:     }
183:     unsafe { mask_all_io_apic_entries(io_apic_virtual, max_redirection_index)? };
184: 
185:     let io_id = unsafe { io_apic_read(io_apic_virtual, IO_APIC_ID) };
186:     if ((io_id >> 24) & 0x0f) as u8 != io_apic.apic_id {
187:         return Err(ApicError::IoApicIdMismatch);
188:     }
189: 
190:     // Check the hardware-reported bootstrap identity before enabling the APIC.
191:     let local_id = unsafe { read_local(local_apic_virtual, APIC_ID) };
192:     if (local_id >> 24) as u8 != bootstrap_apic_id {
193:         return Err(ApicError::BootstrapApicIdMismatch);
194:     }
195: 
196:     let last_gsi = io_apic
197:         .global_system_interrupt_base
198:         .checked_add(u32::from(max_redirection_index))
199:         .ok_or(ApicError::GsiRangeOverflow)?;
200:     let timer_route = madt.resolve_isa_interrupt(0);
201:     if timer_route.global_system_interrupt < io_apic.global_system_interrupt_base
202:         || timer_route.global_system_interrupt > last_gsi
203:     {
204:         return Err(ApicError::TimerGsiOutOfRange);
205:     }
206:     let timer_pin =
207:         (timer_route.global_system_interrupt - io_apic.global_system_interrupt_base) as u8;
208:     let (timer_low_register, _) = redirection_registers(timer_pin, max_redirection_index)
209:         .ok_or(ApicError::TimerGsiOutOfRange)?;
210: 
211:     // SAFETY: The caller guarantees the APIC mapping and disabled-interrupt
212:     // single-CPU setup context. Vector 0xff is reserved for the spurious vector.
213:     unsafe {
214:         write_local(
215:             local_apic_virtual,
216:             APIC_SVR,
217:             APIC_SVR_SOFTWARE_ENABLE as u64 | u64::from(APIC_SPURIOUS_VECTOR),
218:         );
219:     }
220: 
221:     LOCAL_APIC_VIRTUAL.store(local_apic_virtual, Ordering::Relaxed);
222:     IO_APIC_VIRTUAL.store(io_apic_virtual, Ordering::Relaxed);
223:     TIMER_LOW_REGISTER.store(timer_low_register, Ordering::Relaxed);
224:     TIMER_ROUTE_ATTRIBUTES.store(
225:         u8::from(timer_route.polarity == InterruptPolarity::ActiveLow)
226:             | (u8::from(timer_route.trigger == InterruptTrigger::Level) << 1),
227:         Ordering::Relaxed,
228:     );
229:     IO_APIC_GSI_BASE.store(io_apic.global_system_interrupt_base, Ordering::Relaxed);
230:     IO_APIC_MAX_REDIRECTION.store(max_redirection_index, Ordering::Relaxed);
231:     BOOTSTRAP_APIC_ID.store(bootstrap_apic_id, Ordering::Relaxed);
232:     INITIALIZED.store(true, Ordering::Release);
233:     Ok(())
234: }
