236: /// Configure one MADT-resolved ISA route, keeping it masked until explicitly enabled.
237: ///
238: /// # Safety
239: /// Must run on the bootstrap CPU with IF=0 after APIC initialization. The MADT
240: /// must be the validated table used by `initialize`, the source must remain
241: /// disabled until its handler is ready, and no other code may reprogram the APIC.
242: pub unsafe fn configure_isa_irq(madt: &Madt, isa_irq: u8, vector: u8) -> Result<(), ApicError> {
243:     if !interrupts_are_disabled() {
244:         return Err(ApicError::InterruptsEnabled);
245:     }
246:     if !INITIALIZED.load(Ordering::Acquire) {
247:         return Err(ApicError::NotInitialized);
248:     }
249:     if isa_irq >= 16 {
250:         return Err(ApicError::InvalidIsaIrq);
251:     }
252:     if vector < 32 || vector == APIC_SPURIOUS_VECTOR {
253:         return Err(ApicError::InvalidVector);
254:     }
255: 
256:     let route = madt.resolve_isa_interrupt(isa_irq);
257:     let gsi_base = IO_APIC_GSI_BASE.load(Ordering::Relaxed);
258:     let max_index = IO_APIC_MAX_REDIRECTION.load(Ordering::Relaxed);
259:     let last_gsi = gsi_base
260:         .checked_add(u32::from(max_index))
261:         .ok_or(ApicError::GsiRangeOverflow)?;
262:     if route.global_system_interrupt < gsi_base || route.global_system_interrupt > last_gsi {
263:         return Err(ApicError::IsaRouteOutOfRange);
264:     }
265:     let pin = (route.global_system_interrupt - gsi_base) as u8;
266:     let (low_register, high_register) =
267:         redirection_registers(pin, max_index).ok_or(ApicError::IsaRouteOutOfRange)?;
268:     let polarity = route.polarity;
269:     let trigger = route.trigger;
270:     let low = encode_redirection(vector, polarity, trigger, true);
271:     let destination = BOOTSTRAP_APIC_ID.load(Ordering::Relaxed);
272:     let io_apic_virtual = IO_APIC_VIRTUAL.load(Ordering::Relaxed);
273:     // SAFETY: Initialization validated the single I/O APIC mapping and masked
274:     // every entry. The caller keeps this source disabled until its handler is ready.
275:     unsafe {
276:         io_apic_write(io_apic_virtual, high_register, u32::from(destination) << 24);
277:         io_apic_write(io_apic_virtual, low_register, low);
278:     }
279:     ISA_ROUTE_LOW_REGISTERS[usize::from(isa_irq)].store(low_register, Ordering::Release);
280:     Ok(())
281: }
282: 
283: /// Unmask a previously configured MADT-resolved ISA IRQ route.
284: ///
285: /// # Safety
286: /// Must run on the bootstrap CPU with IF=0 after the matching handler and device
287: /// state are ready. The APIC mapping and route must remain exclusively owned.
288: pub unsafe fn unmask_isa_irq(isa_irq: u8, vector: u8) -> Result<(), ApicError> {
289:     if !interrupts_are_disabled() {
290:         return Err(ApicError::InterruptsEnabled);
291:     }
292:     if !INITIALIZED.load(Ordering::Acquire) {
293:         return Err(ApicError::NotInitialized);
294:     }
295:     if isa_irq >= 16 {
296:         return Err(ApicError::InvalidIsaIrq);
297:     }
298:     if vector < 32 || vector == APIC_SPURIOUS_VECTOR {
299:         return Err(ApicError::InvalidVector);
300:     }
301:     let low_register = ISA_ROUTE_LOW_REGISTERS[usize::from(isa_irq)].load(Ordering::Acquire);
302:     if low_register == 0 {
303:         return Err(ApicError::IsaRouteNotConfigured);
304:     }
305:     let io_apic_virtual = IO_APIC_VIRTUAL.load(Ordering::Relaxed);
306:     let entry = unsafe { io_apic_read(io_apic_virtual, low_register) };
307:     if entry as u8 != vector || entry & IO_APIC_REDIR_MASKED == 0 {
308:         return Err(ApicError::IsaRouteNotConfigured);
309:     }
310:     unsafe { io_apic_write(io_apic_virtual, low_register, entry & !IO_APIC_REDIR_MASKED) };
311:     Ok(())
312: }
