314: /// Program PIT channel 0 and configure the resolved ISA IRQ0 I/O APIC entry.
315: ///
316: /// The route is installed masked. A divisor of zero uses the 8254's encoding
317: /// for 65,536 input clocks; values 1 through 65,535 are used literally.
318: ///
319: /// # Safety
320: /// Must execute at CPL 0 on the bootstrap processor with maskable interrupts
321: /// disabled, after successful [`initialize`]. No other code may concurrently
322: /// access the PIT or I/O APIC. The mappings supplied to `initialize` must remain
323: /// valid and retain their documented permissions and cache type.
324: pub unsafe fn configure_pit_timer(vector: u8, divisor: u16) -> Result<(), ApicError> {
325:     if !interrupts_are_disabled() {
326:         return Err(ApicError::InterruptsEnabled);
327:     }
328:     if !INITIALIZED.load(Ordering::Acquire) {
329:         return Err(ApicError::NotInitialized);
330:     }
331:     if vector < 32 || vector == APIC_SPURIOUS_VECTOR {
332:         return Err(ApicError::InvalidVector);
333:     }
334: 
335:     let io_apic_virtual = IO_APIC_VIRTUAL.load(Ordering::Relaxed);
336:     let low_register = TIMER_LOW_REGISTER.load(Ordering::Relaxed);
337:     let high_register = low_register
338:         .checked_add(1)
339:         .ok_or(ApicError::TimerGsiOutOfRange)?;
340:     let destination = BOOTSTRAP_APIC_ID.load(Ordering::Relaxed);
341:     let attributes = TIMER_ROUTE_ATTRIBUTES.load(Ordering::Relaxed);
342:     let polarity = if attributes & 1 != 0 {
343:         InterruptPolarity::ActiveLow
344:     } else {
345:         InterruptPolarity::ActiveHigh
346:     };
347:     let trigger = if attributes & 2 != 0 {
348:         InterruptTrigger::Level
349:     } else {
350:         InterruptTrigger::Edge
351:     };
352:     let route_low = encode_redirection(vector, polarity, trigger, true);
353: 
354:     // Install the destination first, then the masked low dword so no transient
355:     // unmasked route can be observed.
356:     unsafe {
357:         io_apic_write(io_apic_virtual, high_register, u32::from(destination) << 24);
358:         io_apic_write(io_apic_virtual, low_register, route_low);
359:         io::write_u8(PIT_COMMAND, PIT_RATE_GENERATOR_LOHI);
360:         io::write_u8(PIT_CHANNEL_0, divisor as u8);
361:         io::write_u8(PIT_CHANNEL_0, (divisor >> 8) as u8);
362:     }
363: 
364:     TIMER_CONFIGURED.store(true, Ordering::Release);
365:     Ok(())
366: }
367: 
368: /// Unmask only the IRQ0 redirection entry validated by [`initialize`].
369: ///
370: /// # Safety
371: /// Must execute at CPL 0 on the bootstrap processor with maskable interrupts
372: /// disabled, after successful [`configure_pit_timer`]. The I/O APIC mapping
373: /// must remain valid and no other code may modify its redirection table.
374: pub unsafe fn unmask_pit_timer() -> Result<(), ApicError> {
375:     if !interrupts_are_disabled() {
376:         return Err(ApicError::InterruptsEnabled);
377:     }
378:     if !INITIALIZED.load(Ordering::Acquire) {
379:         return Err(ApicError::NotInitialized);
380:     }
381:     if !TIMER_CONFIGURED.load(Ordering::Acquire) {
382:         return Err(ApicError::TimerNotConfigured);
383:     }
384: 
385:     let io_apic_virtual = IO_APIC_VIRTUAL.load(Ordering::Relaxed);
386:     let low_register = TIMER_LOW_REGISTER.load(Ordering::Relaxed);
387:     let entry = unsafe { io_apic_read(io_apic_virtual, low_register) };
388:     unsafe { io_apic_write(io_apic_virtual, low_register, entry & !IO_APIC_REDIR_MASKED) };
389:     Ok(())
390: }
391: 
392: /// Mask the configured ISA IRQ0 route after a timer startup failure.
393: ///
394: /// # Safety
395: /// Must execute at CPL 0 on the bootstrap processor with maskable interrupts
396: /// disabled after successful [`initialize`]. The I/O APIC mapping must remain
397: /// valid and no other code may modify its redirection table.
398: pub unsafe fn mask_pit_timer() -> Result<(), ApicError> {
399:     if !interrupts_are_disabled() {
400:         return Err(ApicError::InterruptsEnabled);
401:     }
402:     if !INITIALIZED.load(Ordering::Acquire) {
403:         return Err(ApicError::NotInitialized);
404:     }
405: 
406:     let io_apic_virtual = IO_APIC_VIRTUAL.load(Ordering::Relaxed);
407:     let low_register = TIMER_LOW_REGISTER.load(Ordering::Relaxed);
408:     let entry = unsafe { io_apic_read(io_apic_virtual, low_register) };
409:     unsafe { io_apic_write(io_apic_virtual, low_register, entry | IO_APIC_REDIR_MASKED) };
410:     TIMER_CONFIGURED.store(false, Ordering::Release);
411:     Ok(())
412: }
