414: /// Send a local-APIC end-of-interrupt notification when initialized.
415: ///
416: /// This is safe to call from the bootstrap CPU's eventual interrupt handler.
417: /// It is a no-op before successful initialization; it does not acknowledge any
418: /// legacy PIC or I/O APIC directly.
419: pub fn end_of_interrupt() {
420:     if INITIALIZED.load(Ordering::Acquire) {
421:         let local_apic_virtual = LOCAL_APIC_VIRTUAL.load(Ordering::Relaxed);
422:         // SAFETY: Initialization publishes this still-mapped page address, and
423:         // the EOI register is a valid aligned register in the local APIC page.
424:         unsafe { write_local(local_apic_virtual, APIC_EOI, 0) };
425:     }
426: }
