428: fn interrupts_are_disabled() -> bool {
429:     let flags: u64;
430:     // SAFETY: Reading RFLAGS is non-mutating and supported in x86_64 mode.
431:     unsafe { core::arch::asm!("pushfq", "pop {}", out(reg) flags) };
432:     flags & (1 << 9) == 0
433: }
434: 
435: fn validate_mapped_page(address: u64) -> Result<(), ApicError> {
436:     if address == 0 || address & 0xfff != 0 || address.checked_add(0xfff).is_none() {
437:         return Err(ApicError::InvalidMappedAddress);
438:     }
439:     Ok(())
440: }
441: 
442: unsafe fn read_msr(msr: u32) -> u64 {
443:     let low: u32;
444:     let high: u32;
445:     // SAFETY: The caller validates the MSR, CPU feature, and CPL requirements.
446:     unsafe {
447:         core::arch::asm!(
448:             "rdmsr",
449:             in("ecx") msr,
450:             out("eax") low,
451:             out("edx") high,
452:             options(nomem, nostack, preserves_flags)
453:         );
454:     }
455:     (u64::from(high) << 32) | u64::from(low)
456: }
457: 
458: unsafe fn write_msr(msr: u32, value: u64) {
459:     // SAFETY: The caller validates the MSR, CPU feature, and CPL requirements.
460:     unsafe {
461:         core::arch::asm!(
462:             "wrmsr",
463:             in("ecx") msr,
464:             in("eax") value as u32,
465:             in("edx") (value >> 32) as u32,
466:             options(nomem, nostack, preserves_flags)
467:         );
468:     }
469: }
470: 
471: unsafe fn read_local(base: u64, offset: u64) -> u32 {
472:     let address = base + offset;
473:     // SAFETY: The caller supplies the mapped APIC page and a checked in-page
474:     // register offset; the resulting pointer is four-byte aligned.
475:     unsafe { read_volatile(address as *const u32) }
476: }
477: 
478: unsafe fn write_local(base: u64, offset: u64, value: u64) {
479:     let address = base + offset;
480:     // SAFETY: The caller supplies the mapped APIC page and a checked in-page
481:     // register offset; the resulting pointer is four-byte aligned.
482:     unsafe { write_volatile(address as *mut u32, value as u32) };
483: }
484: 
485: unsafe fn io_apic_read(base: u64, register: u8) -> u32 {
486:     // SAFETY: The caller supplies the mapped I/O APIC page. Both indirect
487:     // registers are within the first 0x14 bytes of that page.
488:     unsafe {
489:         write_volatile(base as *mut u32, u32::from(register));
490:         read_volatile((base + 0x10) as *const u32)
491:     }
492: }
493: 
494: unsafe fn io_apic_write(base: u64, register: u8, value: u32) {
495:     // SAFETY: The caller supplies the mapped I/O APIC page. Both indirect
496:     // registers are within the first 0x14 bytes of that page.
497:     unsafe {
498:         write_volatile(base as *mut u32, u32::from(register));
499:         write_volatile((base + 0x10) as *mut u32, value);
500:     }
501: }
502: 
503: unsafe fn mask_all_io_apic_entries(base: u64, max_redirection_index: u8) -> Result<(), ApicError> {
504:     let mut pin = 0;
505:     while pin <= max_redirection_index {
506:         let (low, _) = redirection_registers(pin, max_redirection_index)
507:             .ok_or(ApicError::InvalidIoApicVersion)?;
508:         let current = unsafe { io_apic_read(base, low) };
509:         unsafe { io_apic_write(base, low, current | IO_APIC_REDIR_MASKED) };
510:         pin += 1;
511:     }
512:     Ok(())
513: }
514: 
515: unsafe fn mask_local_apic_lvt_entries(base: u64) {
516:     for offset in [
517:         APIC_LVT_TIMER,
518:         APIC_LVT_THERMAL,
519:         APIC_LVT_PERFORMANCE,
520:         APIC_LVT_LINT0,
521:         APIC_LVT_LINT1,
522:         APIC_LVT_ERROR,
523:     ] {
524:         let value = unsafe { read_local(base, offset) };
525:         unsafe { write_local(base, offset, u64::from(value | APIC_LVT_MASKED)) };
526:     }
527: }
